#!/usr/bin/env bash
set -euo pipefail
issuer='http://127.0.0.1:8081/realms/enterprise-mcp-kit'
token() { curl -fsS -X POST "$issuer/protocol/openid-connect/token" -d grant_type=password -d client_id=enterprise-mcp-kit -d "username=$1" -d password=local-demo-only | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>process.stdout.write(JSON.parse(s).access_token))'; }
planner="$(token northstar-planner)"; approver="$(token northstar-approver)"
plan="$(curl -sS -X POST http://127.0.0.1:8787/api/v1/governance/tools/create_action_plan -H "Authorization: Bearer $planner" -H 'content-type: application/json' --data '{"actionType":"netbox.device.update","target":{"kind":"netbox-device","id":"7"},"proposedChange":"Change role.","confidence":0.8,"evidence":[{"source":"api/dcim/devices/7/","summary":"Local lab evidence."}],"ruleVersion":"lab-v1","promptVersion":null,"expiresAt":"2026-12-31T00:00:00.000Z"}')"
id="$(printf %s "$plan" | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{const d=JSON.parse(s);if(typeof d.data?.id!=="string"){console.error(`Create plan failed: ${d.error_code ?? "unknown error"}: ${d.message ?? "no detail"}`);process.exit(1)}process.stdout.write(d.data.id)})')"
curl -sS -X POST http://127.0.0.1:8787/api/v1/governance/tools/approve_action_plan -H "Authorization: Bearer $approver" -H 'content-type: application/json' --data "{\"planId\":\"$id\",\"reason\":\"Approved in local identity lab.\"}" | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{let d=JSON.parse(s);if(d.data?.state!=="approved"||typeof d.data?.approvedBy!=="string"||d.data.approvedBy.length===0||d.data.tenantId!=="northstar"||d.meta?.tenantId!=="northstar"||d.meta?.execution!=="disabled"){console.error(`Approval failed: ${d.error_code ?? "unexpected response"}: ${d.message ?? "no detail"}`);process.exit(1)}console.log("governance-keycloak-live-proof=passed")})'
